unit_tests:
  - name: test_stg_stripe__payments_cents_to_dollars
    description: Amounts arrive in cents and must leave staging in dollars, as exact decimals.
    model: stg_stripe__payments
    given:
      - input: source('stripe', 'payments')
        rows:
          - {id: 1, orderid: 10, paymentmethod: credit_card, status: success, amount: 1250}
          - {id: 2, orderid: 10, paymentmethod: coupon, status: success, amount: 1}
          - {id: 3, orderid: 11, paymentmethod: credit_card, status: fail, amount: 1999}
    expect:
      rows:
        - {payment_id: 1, payment_method: credit_card, amount: 12.50}
        - {payment_id: 2, payment_method: coupon, amount: 0.01}
        - {payment_id: 3, payment_method: credit_card, amount: 19.99}

orders as (

    select * from {{ ref('int_orders__enriched') }}

    {% if is_incremental() %}
    -- only the orders loaded after the newest row already in this table
    -- (coalesce: if the table is empty, for example after --empty, max() is NULL -> take every row)
    where loaded_at > (select coalesce(max(loaded_at), '1900-01-01') from {{ this }})
    {% endif %}

),
